def get_table_definition(tree):
    """
    Get the table definition from the parsed table definition file.
    @param tree: the ElementTree of a table definition file
    @return: the table definition
    """
    return tree.find("table-definition")


def get_table_name(table_definition):
    """
    Get the name of the table from the parsed table definition.
    @param table_definition: the table definition from the parsed table definition file
    @return: the name of the table
    """
    return table_definition.get("name")


def get_table_schema(table_definition):
    """
    Get the schema of the table from the parsed table definition.
    @param table_definition: the table definition from the parsed table definition file
    @return: the schema of the table
    """
    return table_definition.get("schema")


def get_table_columns(table_definition):
